KG42.register("clusters-c699b84b7dfe714856f68887",{"id":"25-p2p_ancillary_bidding::v142-d-CL004","paper":"25-p2p_ancillary_bidding","label":"Utility backstop and rate obligations for unexecuted electrical energy at the end of the CDA period","record":{"cluster_id":"v142-d-CL004","label":"Utility backstop and rate obligations for unexecuted electrical energy at the end of the CDA period","market_meaning":"Demand and supply that remain unexecuted after the CDA ends are, under the assumption that the community is a price taker, supplied by the utility at the retail price and purchased by the utility at the FiT, respectively, forming a P2G residual balancing obligation.","mechanism_ids":["v141-a-M02-residual-balancing","v141-a-M01-p2p-cda"],"market_types":["LEM_DEM","LEM"],"process_stages":["settlement","bidding","matching"],"scope_disposition":"conditional","scope_explanation":"M01 provides only the CDA order-status interface, and M02 bears the subsequent backstop obligation. Only quantities that remain unmatched after the protocol period ends enter M02; the balance left by one local match or a single matching stop cannot be directly regarded as the end-of-period residual quantity.","assembly_status":"partial","boundary_rationale":"Form an independent rule based on the end-of-period unexecuted electrical energy quantity and its utility rate obligation, retaining the mechanism differences from bilateral execution and from ancillary-service-induced agreement adjustments.","chain_bindings":[{"chain_id":"v141-c-R011","ownership":"primary","role":"core","rationale":"Carry the responsibility for supplying residual demand and purchasing residual generation, as well as the price-taker condition."},{"chain_id":"v141-c-R001","ownership":"shared","role":"interface","rationale":"Provide the demand-order balance and completed-removal status, which must pass the end-of-period screening before entering the backstop scope."},{"chain_id":"v141-c-R002","ownership":"shared","role":"interface","rationale":"Provide the supply-order balance and completed-removal status, and do not directly serve as the final total residual generation."},{"chain_id":"v141-c-R006","ownership":"shared","role":"context","rationale":"Explain the CDA matching attempt and stopping conditions; this shared context does not constitute a new dependency edge for the end of the protocol period or the start of the backstop."}],"connections":[{"connection_id":"v142-d-CL004-CON01","from_chain_id":"v141-c-R001","to_chain_id":"v141-c-R011","kind":"functional_coupling","from_refs":["v141-c-R001::x::v141-c-R001-X002","v141-c-R001::phi::v141-c-R001-C002"],"to_refs":["v141-c-R011::phi::v141-c-R011-C001"],"evidence_ids":["v141-b-g01-E09","v141-b-g01-E18","v141-b-g01-E20"],"rationale":"The source assigns demand still unmatched after the CDA to utility supply; this applies only when an order balance still exists at the end of the period, and the balance from one partial match is not equated with the complete end-of-period residual demand."},{"connection_id":"v142-d-CL004-CON02","from_chain_id":"v141-c-R002","to_chain_id":"v141-c-R011","kind":"functional_coupling","from_refs":["v141-c-R002::x::v141-c-R002-x003","v141-c-R002::phi::v141-c-R002-C002"],"to_refs":["v141-c-R011::phi::v141-c-R011-C002"],"evidence_ids":["v141-b-g01-E09","v141-b-g01-E18","v141-b-g01-E20"],"rationale":"Unexecuted supply enters the utility purchase scope only at the end of the CDA period; the interim update state and the end-of-period P2G obligation remain distinguished."},{"connection_id":"v142-d-CL004-CON03","from_chain_id":"v141-c-R006","to_chain_id":"v141-c-R011","kind":"complementary_scope","from_refs":["v141-c-R006::phi::v141-c-R006-C005"],"to_refs":["v141-c-R011::phi::v141-c-R011-C001","v141-c-R011::phi::v141-c-R011-C002"],"evidence_ids":["v141-b-g01-E10","v141-b-g01-E18","v141-b-g01-E21"],"rationale":"The CDA permits the current matching process to stop without further matching, and residual balancing separately handles the electrical energy left after the CDA; here only the complementary scopes are associated, and the current stop is not interpreted as the closure of the protocol period."}],"object_mappings":[],"gaps":[{"gap_id":"v142-d-CL004-G01","category":"upstream_missing","description":"The existing chains do not have a complete end-of-period order-book snapshot, a summary of unexecuted quantities, or a P2G agreement object interface. A partial-match balance does not cover orders that were never matched and does not guarantee that no further execution occurs afterward.","chain_ids":["v141-c-R001","v141-c-R002","v141-c-R006","v141-c-R011"],"object_refs":["v141-c-R001::x::v141-c-R001-X002","v141-c-R002::x::v141-c-R002-x003","v141-c-R006::phi::v141-c-R006-C005","v141-c-R011::phi::v141-c-R011-C001","v141-c-R011::phi::v141-c-R011-C002"],"evidence_ids":["v141-b-g01-E09","v141-b-g01-E18","v141-b-g01-E21"],"proposal_ids":[],"required_work":"Upstream should clarify the reference interfaces for end-of-period screening and P2G agreement generation; D does not use the existing local balance to fabricate the final residual quantity."},{"gap_id":"v142-d-CL004-G02","category":"math_incomplete","description":"R011 retains the qualitative supply/purchase and rate obligations, but there are currently no typed objects for quantity or rate and no mathematical expression for payment; the existing C2 revision request states that the mathematics remains unresolved.","chain_ids":["v141-c-R011"],"object_refs":["v141-c-R011::phi::v141-c-R011-C001","v141-c-R011::phi::v141-c-R011-C002"],"evidence_ids":["v141-b-g01-E18","v141-b-g01-E20"],"proposal_ids":[],"required_work":"Supplement traceable metering and payment representations through explicit upstream revision; the absence of relevant quantities or prices in the source must not be inferred from an empty array."},{"gap_id":"v142-d-CL004-G03","category":"ontology_extension","description":"The utility residual allocation is currently carried only by settlement.payment, and the dedicated allocation-node proposal has not yet been approved.","chain_ids":["v141-c-R011"],"object_refs":["v141-c-R011::V::settlement.payment"],"evidence_ids":["v141-b-g02-E05-residual-balancer-role","v141-b-g02-E06-residual-prices","v141-b-g02-E07-p2g-agreements-eq14"],"proposal_ids":["v141-b-g02-P04-residual-balancing-allocation"],"required_work":"Manually check whether this proposal requires ontology extension; currently only the frozen payment node is referenced, and no new node is inserted."},{"gap_id":"v142-d-CL004-G04","category":"unverified_source","description":"The sources for the residual balancing and CDA interfaces both remain unverified; the cross-mechanism assembly is based on an explicit narrative of unexecuted electrical energy and does not represent the passing of an independent review.","chain_ids":["v141-c-R001","v141-c-R002","v141-c-R006","v141-c-R011"],"object_refs":[],"evidence_ids":["v141-b-g01-E09","v141-b-g01-E18","v141-b-g01-E20","v141-b-g01-E21"],"proposal_ids":[],"required_work":"Manually verify the end-of-period scope, the price-taker assumption, and the direction of electricity supply and purchase."}]},"rule_refs":["25-p2p_ancillary_bidding::v141-c-R011","25-p2p_ancillary_bidding::v141-c-R001","25-p2p_ancillary_bidding::v141-c-R002","25-p2p_ancillary_bidding::v141-c-R006"],"unresolved_rule_refs":[],"node_ids":["COMP-739917e3869e45a6","COMP-c98744ae891e04fd","COMP-ffbf050cce03a2e6","KG40-12aedc3eec573697","KG40-20f45ec4bdcbac06","KG40-404d7eddbf0fc37c"]});
